previewCss:
.darma-loader-darma-b7-newtons-cradle { --accent: var(--loader-color, #64748b); width: var(--loader-size, 84px); height: calc(var(--loader-size, 84px) * .55); display: flex; align-items: flex-start; justify-content: center; }
.darma-loader-darma-b7-newtons-cradle span { width: calc(var(--loader-size, 84px) * .19); height: calc(var(--loader-size, 84px) * .19); border-radius: 50%; background: radial-gradient(circle at 32% 30%, color-mix(in srgb, #fff 55%, var(--accent)), var(--accent)); transform-origin: 50% -160%; }
.darma-loader-darma-b7-newtons-cradle span:first-child { animation: darma-loader-darma-b7-newtons-cradle-cradle-left calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b7-newtons-cradle span:last-child { animation: darma-loader-darma-b7-newtons-cradle-cradle-right calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b7-newtons-cradle-cradle-left { 0%, 50%, 100% { transform: rotate(0); } 25% { transform: rotate(-48deg); } }
@keyframes darma-loader-darma-b7-newtons-cradle-cradle-right { 0%, 50%, 100% { transform: rotate(0); } 75% { transform: rotate(48deg); } }

